      (typeof saveSettingsDebounced === 'function' ? saveSettingsDebounced : null) ||
      window.saveSettingsDebounced ||
      (window.SillyTavern && window.SillyTavern.saveSettingsDebounced);
    if (typeof fn === 'function') fn();
