  STATE.moments = STATE.moments || [];
  STATE.moments.push({
    id: momentId,
    from: 'user',
    name: '我',
    initials: '我',
    avatarBg: 'linear-gradient(145deg,#64748b,#475569)',
    time: ts,
    text,
    img: null,
    likes: [],
    comments: [],
  });
  closeCompose();
  STATE.composeDraft = '';
  go('moments');
  $('#rp-moments-list').scrollTop(0);
